"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useState } from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a dictation button. Pass `listening` to control it, or `defaultListening` to let it hold its own
 * state. The component never opens the microphone: the caller does, and feeds `level` back.
 */
export type VoiceInputProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  listening?: boolean;
  defaultListening?: boolean;
  onListeningChange?: (listening: boolean) => void;
  /** How loud the input is right now, from 0 (silence) to 1. The bars follow it. */
  level?: number;
  /** Runs when the person presses the button to start. Open the microphone here. */
  onStart?: () => void;
  /** Runs when the person presses the button to stop, with the seconds the timer reached. */
  onStop?: (seconds: number) => void;
  /** The accessible name of the button. It stays the same in both states; `aria-pressed` carries the state. */
  label?: string;
  disabled?: boolean;
};

// How far each bar follows the level, so the row reads as a voice and not as one block.
const BAR_WEIGHTS = [0.55, 0.85, 1, 0.7, 0.45];
// A bar never shrinks to nothing: the row stays visible in silence.
const REST = 0.2;
// The level changes many times a second. A critically damped spring retargets without restarting or bouncing.
const LEVEL_SPRING: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const SWAP: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

const clock = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;

function MicGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-5">
      <path d="M8 1a2.5 2.5 0 0 0-2.5 2.5v4a2.5 2.5 0 0 0 5 0v-4A2.5 2.5 0 0 0 8 1Z" />
      <path d="M3.75 7a.75.75 0 0 1 .75.75 3.5 3.5 0 0 0 7 0 .75.75 0 0 1 1.5 0 5 5 0 0 1-4.25 4.94V14.25a.75.75 0 0 1-1.5 0v-1.56A5 5 0 0 1 3 7.75.75.75 0 0 1 3.75 7Z" />
    </svg>
  );
}

function StopGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-5">
      <rect x="3.5" y="3.5" width="9" height="9" rx="2" />
    </svg>
  );
}

/**
 * A microphone button for dictation. Press it and it becomes a stop button, the level bars move with the voice
 * and a timer counts up; press it again to stop. The timer restarts at zero each time listening starts.
 */
export function VoiceInput({
  listening,
  defaultListening = false,
  onListeningChange,
  level = 0,
  onStart,
  onStop,
  label = "Dictate",
  disabled = false,
  className,
  ...divProps
}: VoiceInputProps) {
  const [ownListening, setOwnListening] = useState(defaultListening);
  const [seconds, setSeconds] = useState(0);
  // Nothing is announced until the person has used the button once.
  const [used, setUsed] = useState(false);
  const reduceMotion = useReducedMotion();
  const active = listening ?? ownListening;
  const loudness = Math.min(1, Math.max(0, level));

  // The timer restarts when listening starts, also when the parent starts it. Adjusting during
  // render avoids one frame that shows the previous count.
  const [wasActive, setWasActive] = useState(active);
  if (active !== wasActive) {
    setWasActive(active);
    if (active) setSeconds(0);
  }

  useEffect(() => {
    if (!active) return;
    const timer = window.setInterval(() => setSeconds((count) => count + 1), 1000);
    return () => window.clearInterval(timer);
  }, [active]);

  const toggle = () => {
    setUsed(true);
    if (active) onStop?.(seconds);
    else onStart?.();
    if (listening === undefined) setOwnListening(!active);
    onListeningChange?.(!active);
  };

  const glyphMotion = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8 };

  return (
    <div {...divProps} className={cn("inline-flex items-center gap-3 text-sm text-foreground", className)}>
      <button
        type="button"
        aria-label={label}
        aria-pressed={active}
        disabled={disabled}
        onClick={toggle}
        className={cn(
          "relative flex size-11 shrink-0 cursor-pointer touch-manipulation items-center justify-center rounded-full border outline-none motion-safe:transition-colors motion-safe:duration-150",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-50",
          active ? "border-primary bg-primary text-primary-foreground" : "border-border bg-muted text-foreground",
        )}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={active ? "stop" : "mic"}
            initial={glyphMotion}
            animate={{ opacity: 1, scale: 1 }}
            exit={glyphMotion}
            transition={SWAP}
            className="flex"
          >
            {active ? <StopGlyph /> : <MicGlyph />}
          </motion.span>
        </AnimatePresence>
      </button>
      <span aria-hidden="true" className={cn("flex h-6 items-center gap-1", !active && "text-muted-foreground")}>
        {BAR_WEIGHTS.map((weight, index) => (
          <motion.span
            key={index}
            initial={false}
            // Reduced motion holds the bars still. The stop glyph, the timer and the status still say it is listening.
            animate={{ scaleY: active && !reduceMotion ? REST + (1 - REST) * loudness * weight : REST }}
            transition={reduceMotion ? INSTANT : LEVEL_SPRING}
            className="block h-full w-1 rounded-full bg-current"
          />
        ))}
      </span>
      {/* A timer role is silent by default, so the count does not interrupt a screen reader every second. */}
      <span role="timer" className={cn("w-10 tabular-nums", !active && "text-muted-foreground")}>
        {clock(seconds)}
      </span>
      <span role="status" className="sr-only">
        {used ? (active ? "Listening" : `Stopped after ${clock(seconds)}`) : ""}
      </span>
    </div>
  );
}
